1	import { existsSync } from 'node:fs';
2	import { builtinModules } from 'node:module';
3	import { fileURLToPath, pathToFileURL } from 'node:url';
4	import type { AstroIntegrationLogger } from 'astro';
5	import {
6		ASTRO_LOCALS_HEADER,
7		ASTRO_MIDDLEWARE_SECRET_HEADER,
8		ASTRO_PATH_HEADER,
9		NODE_PATH,
10	} from '../index.js';
11	
12	/**
13	 * It generates the Vercel Edge Middleware file.
14	 *
15	 * It creates a temporary file, the edge middleware, with some dynamic info.
16	 *
17	 * Then this file gets bundled with esbuild. The bundle phase will inline the Astro middleware code.
18	 *
19	 * @param astroMiddlewareEntryPointPath
20	 * @param root
21	 * @param vercelEdgeMiddlewareHandlerPath
22	 * @param outPath
23	 * @param middlewareSecret
24	 * @param logger
25	 * @returns {Promise<URL>} The path to the bundled file
26	 */
27	export async function generateEdgeMiddleware(
28		astroMiddlewareEntryPointPath: URL,
29		root: URL,
30		vercelEdgeMiddlewareHandlerPath: URL,
31		outPath: URL,
32		middlewareSecret: string,
33		logger: AstroIntegrationLogger,
34	): Promise<URL> {
35		const code = edgeMiddlewareTemplate(
36			astroMiddlewareEntryPointPath,
37			vercelEdgeMiddlewareHandlerPath,
38			middlewareSecret,
39			logger,
40		);
41		// https://vercel.com/docs/concepts/functions/edge-middleware#create-edge-middleware
42		const bundledFilePath = fileURLToPath(outPath);
43		const esbuild = await import('esbuild');
44		try {
45			await esbuild.build({
46				stdin: {
47					contents: code,
48					resolveDir: fileURLToPath(root),
49				},
50				// Vercel Edge runtime targets ESNext, because Cloudflare Workers update v8 weekly
51				// https://github.com/vercel/vercel/blob/1006f2ae9d67ea4b3cbb1073e79d14d063d42436/packages/next/scripts/build-edge-function-template.js
52				target: 'esnext',
53				platform: 'browser',
54				// esbuild automatically adds the browser, import and default conditions
55				// https://esbuild.github.io/api/#conditions
56				// https://runtime-keys.proposal.wintercg.org/#edge-light
57				conditions: ['edge-light', 'workerd', 'worker'],
58				outfile: bundledFilePath,
59				allowOverwrite: true,
60				format: 'esm',
61				bundle: true,
62				minify: false,
63				// ensure node built-in modules are namespaced with `node:`
64				plugins: [
65					{
66						name: 'esbuild-namespace-node-built-in-modules',
67						setup(build) {
68							const filter = new RegExp(builtinModules.map((mod) => `(^${mod}$)`).join('|'));
69							build.onResolve(
70								{
71									filter,
72								},
73								(args) => ({
74									path: 'node:' + args.path,
75									external: true,
76								}),
77							);
78						},
79					},
80				],
81			});
82		} catch (err) {
83			if ((err as Error).message.includes('Could not resolve "node:')) {
84				logger.error(
85					`Vercel does not allow the use of Node.js built-ins in edge functions. Please ensure your middleware code and 3rd-party packages don’t use Node built-ins.`,
86				);
87			}
88	
89			throw err;
90		}
91		return pathToFileURL(bundledFilePath);
92	}
93	
94	function edgeMiddlewareTemplate(
95		astroMiddlewareEntryPointPath: URL,
96		vercelEdgeMiddlewareHandlerPath: URL,
97		middlewareSecret: string,
98		logger: AstroIntegrationLogger,
99	) {
100		const middlewarePath = JSON.stringify(
101			fileURLToPath(astroMiddlewareEntryPointPath).replace(/\\/g, '/'),
