225		includeFiles: _includeFiles = [],
226		excludeFiles: _excludeFiles = [],
227		imageService,
228		imagesConfig,
229		devImageService = 'sharp',
230		middlewareMode,
231		edgeMiddleware,
232		maxDuration,
233		isr = false,
234		skewProtection = process.env.VERCEL_SKEW_PROTECTION_ENABLED === '1',
235		staticHeaders = false,
