27	export async function generateEdgeMiddleware(
28		astroMiddlewareEntryPointPath: URL,
29		root: URL,
30		vercelEdgeMiddlewareHandlerPath: URL,
31		outPath: URL,
32		middlewareSecret: string,
33		logger: AstroIntegrationLogger,
34	): Promise<URL> {
35		const code = edgeMiddlewareTemplate(
36			astroMiddlewareEntryPointPath,
37			vercelEdgeMiddlewareHandlerPath,
