39			logger,
40		);
41		// https://vercel.com/docs/concepts/functions/edge-middleware#create-edge-middleware
42		const bundledFilePath = fileURLToPath(outPath);
43		const esbuild = await import('esbuild');
44		try {
45			await esbuild.build({
46				stdin: {
47					contents: code,
48					resolveDir: fileURLToPath(root),
49				},
50				// Vercel Edge runtime targets ESNext, because Cloudflare Workers update v8 weekly
51				// https://github.com/vercel/vercel/blob/1006f2ae9d67ea4b3cbb1073e79d14d063d42436/packages/next/scripts/build-edge-function-template.js
52				target: 'esnext',
53				platform: 'browser',
54				// esbuild automatically adds the browser, import and default conditions
55				// https://esbuild.github.io/api/#conditions
56				// https://runtime-keys.proposal.wintercg.org/#edge-light
57				conditions: ['edge-light', 'workerd', 'worker'],
58				outfile: bundledFilePath,
59				allowOverwrite: true,
60				format: 'esm',
61				bundle: true,
62				minify: false,
63				// ensure node built-in modules are namespaced with `node:`
64				plugins: [
65					{
66						name: 'esbuild-namespace-node-built-in-modules',
67						setup(build) {
68							const filter = new RegExp(builtinModules.map((mod) => `(^${mod}$)`).join('|'));
69							build.onResolve(
70								{
71									filter,
72								},
73								(args) => ({
74									path: 'node:' + args.path,
75									external: true,
